// ---- math -------------------------------------------------------------------

constexpr float kPi = 3.14159265F;
constexpr float kDegToRad = 0.01745329F;
constexpr float kRadToDeg = 57.29578F;

/** A position or direction. Converts from the engine's Tyra::Vec4 (so
 * ctx.playerPosition reads as one) and from a float[3] (Vec3::from). */
struct Vec3 {
  float x = 0.0F, y = 0.0F, z = 0.0F;

  constexpr Vec3() = default;
  constexpr Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}
  Vec3(const Tyra::Vec4& v) : x(v.x), y(v.y), z(v.z) {}  // NOLINT: implicit on purpose
  static Vec3 from(const float* p) { return Vec3(p[0], p[1], p[2]); }
  void store(float* p) const { p[0] = x; p[1] = y; p[2] = z; }
  Tyra::Vec4 vec4() const { return Tyra::Vec4(x, y, z); }

  Vec3 operator+(const Vec3& o) const { return Vec3(x + o.x, y + o.y, z + o.z); }
  Vec3 operator-(const Vec3& o) const { return Vec3(x - o.x, y - o.y, z - o.z); }
  Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
  Vec3 operator/(float s) const {
    return (s > -1e-6F && s < 1e-6F) ? Vec3() : Vec3(x / s, y / s, z / s);
  }
  Vec3 operator-() const { return Vec3(-x, -y, -z); }
  Vec3& operator+=(const Vec3& o) { x += o.x; y += o.y; z += o.z; return *this; }
  Vec3& operator-=(const Vec3& o) { x -= o.x; y -= o.y; z -= o.z; return *this; }
  Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }

  static constexpr Vec3 zero() { return Vec3(0.0F, 0.0F, 0.0F); }
  static constexpr Vec3 up() { return Vec3(0.0F, 1.0F, 0.0F); }
  /** +Z: what yaw 0 faces (the walker's and Look At's convention). */
  static constexpr Vec3 forward() { return Vec3(0.0F, 0.0F, 1.0F); }
};

inline Vec3 operator*(float s, const Vec3& v) { return v * s; }
inline float dot(const Vec3& a, const Vec3& b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
inline Vec3 cross(const Vec3& a, const Vec3& b) {
  return Vec3(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x);
}
inline float lengthSq(const Vec3& v) { return dot(v, v); }
inline float length(const Vec3& v) { return sqrtf(dot(v, v)); }
/** Unit length, or zero for a (near) zero vector - never a NaN. */
inline Vec3 normalize(const Vec3& v) {
  const float l = length(v);
  return l > 1e-6F ? v * (1.0F / l) : Vec3();
}
inline float distanceSq(const Vec3& a, const Vec3& b) { return lengthSq(a - b); }
inline float distance(const Vec3& a, const Vec3& b) { return length(a - b); }
/** Distance on the ground plane, ignoring height. */
inline float distanceXZ(const Vec3& a, const Vec3& b) {
  const float dx = a.x - b.x, dz = a.z - b.z;
  return sqrtf(dx * dx + dz * dz);
}

/** Clamp, tolerating swapped bounds (the Clamp node does too). */
inline float clamp(float v, float lo, float hi) {
  if (lo > hi) { const float t = lo; lo = hi; hi = t; }
  return v < lo ? lo : (v > hi ? hi : v);
}
inline float clamp01(float v) { return v < 0.0F ? 0.0F : (v > 1.0F ? 1.0F : v); }
inline float lerp(float a, float b, float t) { return a + (b - a) * t; }
inline Vec3 lerp(const Vec3& a, const Vec3& b, float t) { return a + (b - a) * t; }
/** Where v sits between a and b as 0..1 (unclamped); 0 when a == b. */
inline float inverseLerp(float a, float b, float v) {
  const float d = b - a;
  return (d > -1e-6F && d < 1e-6F) ? 0.0F : (v - a) / d;
}
/** The Remap Range node: x from [i0, i1] onto [o0, o1], clamped; a zero-width
 * input range maps to o0 instead of dividing by zero. */
inline float remap(float x, float i0, float i1, float o0, float o1) {
  return o0 + (o1 - o0) * clamp01(inverseLerp(i0, i1, x));
}
inline float smoothstep(float e0, float e1, float x) {
  const float t = clamp01(inverseLerp(e0, e1, x));
  return t * t * (3.0F - 2.0F * t);
}
inline float sign(float x) { return x > 0.0F ? 1.0F : (x < 0.0F ? -1.0F : 0.0F); }
/** The Divide node: a zero divisor yields 0, not a NaN. */
inline float safeDiv(float a, float b) {
  return (b > -1e-6F && b < 1e-6F) ? 0.0F : a / b;
}
/** Steps current toward target by at most maxDelta, never past it. */
inline float moveTowards(float current, float target, float maxDelta) {
  const float d = target - current;
  if (d <= maxDelta && d >= -maxDelta) return target;
  return current + (d > 0.0F ? maxDelta : -maxDelta);
}
inline Vec3 moveTowards(const Vec3& current, const Vec3& target, float maxDelta) {
  const Vec3 d = target - current;
  const float l = length(d);
  if (l <= maxDelta || l < 1e-6F) return target;
  return current + d * (maxDelta / l);
}
/** An angle in degrees folded into (-180, 180]. */
inline float wrapDeg(float deg) {
  deg = fmodf(deg, 360.0F);
  if (deg > 180.0F) deg -= 360.0F;
  if (deg <= -180.0F) deg += 360.0F;
  return deg;
}
/** The shortest signed turn from `from` to `to`, degrees. */
inline float deltaAngle(float from, float to) { return wrapDeg(to - from); }
inline float moveTowardsAngle(float current, float target, float maxDelta) {
  return current + moveTowards(0.0F, deltaAngle(current, target), maxDelta);
}
/** The yaw (degrees, Y rotation) that faces `to` from `from`; 0 = +Z. */
inline float yawTo(const Vec3& from, const Vec3& to) {
  return atan2f(to.x - from.x, to.z - from.z) * kRadToDeg;
}
/** The ground direction a yaw faces: (sin, 0, cos). */
inline Vec3 forwardFromYaw(float yawDeg) {
  return Vec3(sinf(yawDeg * kDegToRad), 0.0F, cosf(yawDeg * kDegToRad));
}
/** The direction an object's +Z points at after its Euler rotation
 * (degrees, the engine's Rz*Ry*Rx) - Camera From Object's convention. */
inline Vec3 forwardFromRotation(const Vec3& rotDeg) {
  const float sx = sinf(rotDeg.x * kDegToRad), cx = cosf(rotDeg.x * kDegToRad);
  const float sy = sinf(rotDeg.y * kDegToRad), cy = cosf(rotDeg.y * kDegToRad);
  const float sz = sinf(rotDeg.z * kDegToRad), cz = cosf(rotDeg.z * kDegToRad);
  return Vec3(cx * sy * cz + sx * sz, cx * sy * sz - sx * cz, cx * cy);
}

/** Easing curves. The first four are the Tween Value node's (same numbers). */
enum class Ease {
  Linear = 0,
  In = 1,      // quadratic in
  Out = 2,     // quadratic out
  Smooth = 3,  // smoothstep
  InCubic,
  OutCubic,
  InOutCubic,
  OutBack,    // overshoots a little, then settles
  OutBounce,
};
/** t clamped to 0..1, then shaped. */
inline float ease(float t, Ease e) {
  t = clamp01(t);
  switch (e) {
    case Ease::In: return t * t;
    case Ease::Out: return t * (2.0F - t);
    case Ease::Smooth: return t * t * (3.0F - 2.0F * t);
    case Ease::InCubic: return t * t * t;
    case Ease::OutCubic: { const float u = 1.0F - t; return 1.0F - u * u * u; }
    case Ease::InOutCubic: {
      if (t < 0.5F) return 4.0F * t * t * t;
      const float u = -2.0F * t + 2.0F;
      return 1.0F - u * u * u * 0.5F;
    }
    case Ease::OutBack: {
      const float c1 = 1.70158F, c3 = c1 + 1.0F, u = t - 1.0F;
      return 1.0F + c3 * u * u * u + c1 * u * u;
    }
    case Ease::OutBounce: {
      const float n1 = 7.5625F, d1 = 2.75F;
      if (t < 1.0F / d1) return n1 * t * t;
      if (t < 2.0F / d1) { t -= 1.5F / d1; return n1 * t * t + 0.75F; }
      if (t < 2.5F / d1) { t -= 2.25F / d1; return n1 * t * t + 0.9375F; }
      t -= 2.625F / d1;
      return n1 * t * t + 0.984375F;
    }
    default: return t;
  }
}
/** The Tween Value node: `from` -> `to` over `seconds`, `elapsed` in. */
inline float tween(float elapsed, float seconds, float from, float to,
                   Ease e = Ease::Linear) {
  const float t = seconds > 0.0001F ? ease(elapsed / seconds, e) : 1.0F;
  return from + (to - from) * t;
}
inline Vec3 tween(float elapsed, float seconds, const Vec3& from, const Vec3& to,
                  Ease e = Ease::Linear) {
  const float t = seconds > 0.0001F ? ease(elapsed / seconds, e) : 1.0F;
  return lerp(from, to, t);
}

// ---- random -----------------------------------------------------------------
// One xorshift32 for the whole game, shared with the flow graphs' Random
// Branch / Roll Random. Seeded from a constant: a run that reproduces is worth
// more than one that surprises (input replays rely on it). Stir it with
// seedRandom() from a save value for a different game each session.

inline uint32_t g_randState = 0x1234567U;
inline void seedRandom(uint32_t seed) { g_randState = seed ? seed : 0x1234567U; }
inline uint32_t randomU32() {
  uint32_t x = g_randState;
  x ^= x << 13;
  x ^= x >> 17;
  x ^= x << 5;
  g_randState = x;
  return x;
}
/** 0..1 inclusive. */
inline float random01() { return (float)(randomU32() & 0xFFFFU) / 65535.0F; }
/** A float in [lo, hi] (bounds may be swapped). */
inline float randomRange(float lo, float hi) {
  if (lo > hi) { const float t = lo; lo = hi; hi = t; }
  return lo + (hi - lo) * random01();
}
/** A whole number in [lo, hi], both ends inclusive - a 1..6 die can roll 6
 * (Roll Random with "whole"). */
inline int randomInt(int lo, int hi) {
  if (lo > hi) { const int t = lo; lo = hi; hi = t; }
  return lo + (int)(randomU32() % (uint32_t)(hi - lo + 1));
}
/** True with probability p (0..1). */
inline bool chance(float p) { return random01() < p; }
/** A uniform point in a flat disc of radius r around the origin (XZ). */
inline Vec3 randomInCircle(float r) {
  const float a = randomRange(0.0F, 2.0F * kPi);
  const float d = r * sqrtf(random01());
  return Vec3(cosf(a) * d, 0.0F, sinf(a) * d);
}

// ---- time ---------------------------------------------------------------------

namespace detail {
inline float g_time = 0.0F;
inline unsigned int g_timeGeneration = ~0u;
inline unsigned int g_frame = 0;
/** Advanced once per frame by the object-script driver (always compiled in),
 * before any object script runs. */
inline void tick(const ScriptContext& ctx) {
  ++g_frame;
  if (ctx.sceneGeneration != g_timeGeneration) {
    g_timeGeneration = ctx.sceneGeneration;
    g_time = 0.0F;
  } else {
    g_time += g_frameDt;
  }
}
}  // namespace detail

/** Seconds this frame lasted (PAL and NTSC play the same when you multiply
 * speeds by it). */
inline float dt() { return g_frameDt; }
/** Seconds since the active scene (re)loaded - the Scene Time node. */
inline float sceneTime() { return detail::g_time; }
/** Frames since boot. */
inline unsigned int frame() { return detail::g_frame; }

/** A one-shot countdown on the scene clock: start(2.0F), then finished()
 * reports true ONCE when the two seconds are up. */
struct Timer {
  float endsAt = -1.0F;
  void start(float seconds) { endsAt = sceneTime() + (seconds > 0.0F ? seconds : 0.0F); }
  void stop() { endsAt = -1.0F; }
  bool running() const { return endsAt >= 0.0F && sceneTime() < endsAt; }
  float remaining() const {
    return endsAt < 0.0F ? 0.0F : (endsAt > sceneTime() ? endsAt - sceneTime() : 0.0F);
  }
  bool finished() {
    if (endsAt < 0.0F || sceneTime() < endsAt) return false;
    endsAt = -1.0F;
    return true;
  }
};

/** The Cooldown node: use(seconds) succeeds, then refuses until the time has
 * passed. */
struct Cooldown {
  float readyAt = 0.0F;
  bool ready() const { return sceneTime() >= readyAt; }
  bool use(float seconds) {
    if (!ready()) return false;
    readyAt = sceneTime() + seconds;
    return true;
  }
  void reset() { readyAt = 0.0F; }
};

// ---- objects ------------------------------------------------------------------

inline float terrainHeight(const ScriptContext& ctx, float x, float z) {
  return terrainHeightAtScene(ctx.scene, x, z);
}

/** An object of the active scene, by index into ctx.objects. Cheap to copy;
 * everything it does checks that the index is still valid, so a stale or
 * empty ref is a no-op rather than a crash. Writes set the flags the game
 * reads (dirty, restFrames) the way the flow nodes do. */
class ObjectRef {
 public:
  ObjectRef() = default;
  ObjectRef(ScriptContext* c, int index) : ctx_(c), index_(index) {}

  bool valid() const { return ctx_ && index_ >= 0 && index_ < ctx_->objectCount; }
  explicit operator bool() const { return valid(); }
  int index() const { return valid() ? index_ : -1; }
  RuntimeObject* get() const { return valid() ? &ctx_->objects[index_] : nullptr; }
  RuntimeObject* operator->() const { return get(); }
  bool operator==(const ObjectRef& o) const { return index() == o.index(); }
  bool operator!=(const ObjectRef& o) const { return index() != o.index(); }
  ScriptContext* context() const { return ctx_; }

  /** scene_data.hpp's SceneObjectData::type (0 box ... 17 area ...). */
  int type() const { return valid() ? get()->data.type : -1; }
  /** False while its streaming layer is unloaded (out of the game). */
  bool active() const { return valid() && get()->active; }

  // -- transform (Set Object Position / Move Object By / Set Rotation ...)
  Vec3 position() const { return valid() ? Vec3::from(get()->data.position) : Vec3(); }
  void setPosition(const Vec3& p) const {
    if (RuntimeObject* o = get()) { p.store(o->data.position); moved(*o); }
  }
  void moveBy(const Vec3& d) const { setPosition(position() + d); }
  Vec3 rotation() const { return valid() ? Vec3::from(get()->data.rotation) : Vec3(); }
  void setRotation(const Vec3& degrees) const {
    if (RuntimeObject* o = get()) { degrees.store(o->data.rotation); moved(*o); }
  }
  /** Adds degrees, keeping each angle inside (-360, 360) where float degrees
   * still resolve well (Rotate Object By). */
  void rotateBy(const Vec3& degrees) const {
    if (RuntimeObject* o = get()) {
      const float d[3] = {degrees.x, degrees.y, degrees.z};
      for (int a = 0; a < 3; ++a) o->data.rotation[a] = fmodf(o->data.rotation[a] + d[a], 360.0F);
      moved(*o);
    }
  }
  float yaw() const { return valid() ? get()->data.rotation[1] : 0.0F; }
  void setYaw(float degrees) const {
    if (RuntimeObject* o = get()) { o->data.rotation[1] = degrees; moved(*o); }
  }
  /** Where the object's +Z points after its rotation. */
  Vec3 forward() const { return forwardFromRotation(rotation()); }
  Vec3 scale() const { return valid() ? Vec3::from(get()->data.scale) : Vec3(); }
  /** Scale is baked into the vertices, so it always rebuilds the object. */
  void setScale(const Vec3& s) const {
    RuntimeObject* o = get();
    if (!o || same3(o->data.scale, s)) return;
    s.store(o->data.scale);
    o->dirty = true;
  }
  void setScale(float s) const { setScale(Vec3(s, s, s)); }
  /** The Look At node: yaw toward `target` (0 = +Z); tilt also pitches. A
   * target on top of the object leaves the rotation alone. */
  void lookAt(const Vec3& target, bool tilt = false) const {
    RuntimeObject* o = get();
    if (!o) return;
    const Vec3 d = target - position();
    const float flat = sqrtf(d.x * d.x + d.z * d.z);
    if (flat < 0.0001F && (!tilt || fabsf(d.y) < 0.0001F)) return;
    if (flat >= 0.0001F) o->data.rotation[1] = atan2f(d.x, d.z) * kRadToDeg;
    o->data.rotation[0] = tilt ? -atan2f(d.y, flat) * kRadToDeg : 0.0F;
    o->data.rotation[2] = 0.0F;
    moved(*o);
  }
  /** The Spin Object node: turn continuously, degrees per SECOND per axis.
   * The game integrates it (and keeps the object on the cheap matrix path). */
  void spin(const Vec3& degPerSecond) const {
    if (RuntimeObject* o = get()) degPerSecond.store(o->spinRate);
  }

  // -- look
  Vec3 color() const { return valid() ? Vec3::from(get()->data.color) : Vec3(); }
  /** RGB 0..1: mesh tint, particle tint, a free parameter on an Empty. */
  /** A colour change re-bakes the mesh (the colour lives in its vertices):
   * the same colour again is free, so calling this every frame with a value
   * that rarely changes costs nothing. */
  void setColor(const Vec3& rgb) const {
    RuntimeObject* o = get();
    if (!o || same3(o->data.color, rgb)) return;
    rgb.store(o->data.color);
    o->dirty = true;
  }
  bool visible() const { return valid() && get()->visible; }
  /** Set Object Visible: also mutes sound emitters and stops particle
   * emitters. */
  void setVisible(bool v) const {
    if (RuntimeObject* o = get()) o->visible = v;
  }
  void show() const { setVisible(true); }
  void hide() const { setVisible(false); }
  void toggleVisible() const { setVisible(!visible()); }
  bool usable() const { return valid() && get()->data.usable != 0; }
  void setUsable(bool u) const {
    if (RuntimeObject* o = get()) o->data.usable = u ? 1 : 0;
  }
  /** Set Light on a Point Light with "Dynamic (live)": on/off and a
   * multiplier on its authored brightness. */
  void setLight(bool on, float intensity = 1.0F) const {
    if (!valid() || !ctx_->lightRequest) return;
    ctx_->lightRequest[index_] = on ? 1 : 0;
    ctx_->lightIntensity[index_] = intensity < 0.0F ? 0.0F : intensity;
  }

  // -- physics (objects with Physics: rigid body)
  /** Units per SECOND (the game stores per-frame displacements). */
  Vec3 velocity() const {
    const RuntimeObject* o = get();
    if (!o || g_frameDt <= 0.0001F) return Vec3();
    return Vec3(o->velocityX, o->velocityY, o->velocityZ) * (1.0F / g_frameDt);
  }
  void setVelocity(const Vec3& unitsPerSecond) const {
    if (RuntimeObject* o = get()) {
      o->velocityX = unitsPerSecond.x * g_frameDt;
      o->velocityY = unitsPerSecond.y * g_frameDt;
      o->velocityZ = unitsPerSecond.z * g_frameDt;
      o->restFrames = 0;
    }
  }
  /** Apply Impulse: adds to the velocity (units per second) and wakes it. */
  void addImpulse(const Vec3& unitsPerSecond) const {
    if (RuntimeObject* o = get()) {
      o->velocityX += unitsPerSecond.x * g_frameDt;
      o->velocityY += unitsPerSecond.y * g_frameDt;
      o->velocityZ += unitsPerSecond.z * g_frameDt;
      o->restFrames = 0;
    }
  }
  /** Stop Motion: velocity, tumble and Spin Object rate all to zero. */
  void stopMotion() const {
    if (RuntimeObject* o = get()) {
      o->velocityX = o->velocityY = o->velocityZ = 0.0F;
      for (int a = 0; a < 3; ++a) o->spin[a] = o->spinRate[a] = 0.0F;
    }
  }
  bool asleep() const { return valid() && physAsleep(*get()); }

  // -- animated models
  void playAnimation(const char* clip = "", bool loop = true, float speed = 1.0F,
                     float fade = 0.0F) const {
    if (valid()) ::Script_framework::playAnimation(*ctx_, index_, clip, loop, speed, fade);
  }
  void stopAnimation() const {
    if (valid()) ::Script_framework::stopAnimation(*ctx_, index_);
  }
  bool animationFinished() const {
    return valid() && ::Script_framework::animationFinished(*ctx_, index_);
  }

  // -- questions
  float distanceTo(const Vec3& p) const { return distance(position(), p); }
  float distanceTo(const ObjectRef& o) const { return distance(position(), o.position()); }
  /** Area objects: is the point inside its (rotated) box? */
  bool contains(const Vec3& p) const {
    return valid() && pointInArea(get()->data, p.x, p.y, p.z);
  }
  /** Spawned clones can be freed; authored objects only deactivate. */
  void despawn() const {
    if (valid() && ctx_->despawnObject) ctx_->despawnObject(index_);
  }

 private:
  // Position and rotation: wake a sleeping body, and ask for the per-object
  // matrix path. A script that moves something usually moves it EVERY frame,
  // and `dirty` re-bakes the whole mesh in world space on the EE each time -
  // nine bobbing spheres took a level from 50 to 12.5 FPS. Promoted, the new
  // transform is a matrix refresh VU1 applies for free; until the game has
  // promoted it (the next frame) the move still needs the re-bake.
  static void moved(RuntimeObject& o) {
    o.restFrames = 0;
    o.wantsMatrixPath = true;
    if (!o.onMatrixPath) o.dirty = true;
  }
  static bool same3(const float* a, const Vec3& b) {
    return a[0] == b.x && a[1] == b.y && a[2] == b.z;
  }

  ScriptContext* ctx_ = nullptr;
  int index_ = -1;
};

/** An object by its generated id (tyrax::Objects::<Scene>::<Name>). Empty
 * when the id belongs to another scene than the active one. */
inline ObjectRef object(ScriptContext& ctx, ObjectId id) {
  return id.scene == ctx.scene ? ObjectRef(&ctx, id.index) : ObjectRef();
}
/** An object by index into ctx.objects (a raycast hit, a spawned clone). */
inline ObjectRef object(ScriptContext& ctx, int index) { return ObjectRef(&ctx, index); }

/** FNV-1a, the hash names.gen.hpp's OBJECT_NAME_HASHES are made of. */
constexpr uint32_t nameHash(const char* s) {
  uint32_t h = 2166136261U;
  while (*s) { h ^= (uint32_t)(unsigned char)*s++; h *= 16777619U; }
  return h;
}
/** An authored object of the active scene by its editor name (exact match).
 * Prefer the typed ids; this is for names built at runtime. */
inline ObjectRef findObject(ScriptContext& ctx, const char* name) {
  if (ctx.scene < 0 || ctx.scene >= SCENE_COUNT) return ObjectRef();
  const uint32_t h = nameHash(name);
  const uint32_t* table = OBJECT_NAME_HASHES[ctx.scene];
  const int n = OBJECT_NAME_COUNTS[ctx.scene];
  for (int i = 0; i < n && i < ctx.objectCount; ++i)
    if (table[i] == h) return ObjectRef(&ctx, i);
  return ObjectRef();
}

/** Which objects a search looks at. */
struct ObjectFilter {
  int type = -1;            // SceneObjectData::type, -1 = any
  bool visibleOnly = false;
  int exclude = -1;         // an index to skip (usually yourself)
  bool (*accept)(const RuntimeObject&) = nullptr;  // your own test
};
inline bool filterAccepts(const ObjectFilter& f, const RuntimeObject& o, int i) {
  if (!o.active || i == f.exclude) return false;
  if (f.type >= 0 && o.data.type != f.type) return false;
  if (f.visibleOnly && !o.visible) return false;
  return !f.accept || f.accept(o);
}

/** Find Nearest: the closest active object to `p` within maxDist (0 = no
 * limit) that passes the filter. Empty ref when none. */
inline ObjectRef findNearest(ScriptContext& ctx, const Vec3& p, float maxDist = 0.0F,
                             const ObjectFilter& f = ObjectFilter()) {
  int best = -1;
  float bestD = maxDist > 0.0F ? maxDist * maxDist : 1e30F;
  for (int i = 0; i < ctx.objectCount; ++i) {
    const RuntimeObject& o = ctx.objects[i];
    if (!filterAccepts(f, o, i)) continue;
    const float d = distanceSq(Vec3::from(o.data.position), p);
    if (d < bestD) { bestD = d; best = i; }
  }
  return ObjectRef(&ctx, best);
}
/** Every active object within `radius` of `p`, up to `max` of them, into
 * `out`. Returns how many it wrote. */
inline int overlapSphere(ScriptContext& ctx, const Vec3& p, float radius, ObjectRef* out,
                         int max, const ObjectFilter& f = ObjectFilter()) {
  int n = 0;
  const float r2 = radius * radius;
  for (int i = 0; i < ctx.objectCount && n < max; ++i) {
    const RuntimeObject& o = ctx.objects[i];
    if (!filterAccepts(f, o, i)) continue;
    if (distanceSq(Vec3::from(o.data.position), p) <= r2) out[n++] = ObjectRef(&ctx, i);
  }
  return n;
}

/** Spawn Object: a clone of `templ` at `p` facing `yaw` degrees, in a free
 * runtime slot. Empty ref when the pool is full. */
inline ObjectRef spawn(ScriptContext& ctx, const ObjectRef& templ, const Vec3& p,
                       float yaw = 0.0F) {
  if (!templ.valid() || !ctx.spawnObject) return ObjectRef();
  return ObjectRef(&ctx, ctx.spawnObject(templ.index(), p.x, p.y, p.z, yaw));
}

// ---- the player -------------------------------------------------------------

/** The player (camera) position this frame. */
inline Vec3 playerPosition(const ScriptContext& ctx) { return ctx.playerPosition; }
/** The normalized view direction. */
inline Vec3 playerLook(const ScriptContext& ctx) { return ctx.playerLook; }
/** The Player object (third person / FPP walker), empty in scenes without. */
inline ObjectRef playerObject(ScriptContext& ctx) {
  if (ctx.scene < 0 || ctx.scene >= SCENE_COUNT) return ObjectRef();
  return ObjectRef(&ctx, PLAYER_INDEXES[ctx.scene]);
}
/** Distance from a point to the nearer of the (up to two) players. */
inline float distanceToPlayer(const ScriptContext& ctx, const Vec3& p) {
  const float d1 = distance(p, Vec3(ctx.playerPosition));
  if (!ctx.player2Active) return d1;
  const float d2 = distance(p, Vec3(ctx.player2Position));
  return d2 < d1 ? d2 : d1;
}
/** Teleport Player / Spawn Player At: applied by the game after the scripts. */
inline void teleportPlayer(ScriptContext& ctx, const Vec3& p, float yawDeg) {
  ctx.teleport = true;
  ctx.teleportPos = p.vec4();
  ctx.teleportYaw = yawDeg;
}
/** Set Player Input: false freezes the walker's pad (gravity still runs). */
inline void setPlayerInput(ScriptContext& ctx, bool enabled) { ctx.lockInput = enabled ? 1 : 0; }
inline void setFlashlight(ScriptContext& ctx, bool on) { ctx.flashlight = on ? 1 : 0; }
/** Vibrate Pad: big = heavy motor 0..1, small = the buzz motor. */
inline void vibrate(ScriptContext& ctx, float big, bool small = false, float seconds = 0.0F) {
  padVibrate(ctx, big, small, seconds);
}

// ---- queries --------------------------------------------------------------------

/** What a ray found. object is empty for the terrain (or nothing). */
struct RayHit {
  bool hit = false;
  float distance = 0.0F;
  Vec3 point;
  ObjectRef object;
};

namespace detail {
/** The game's own sweep (collision boxes as the walker and the camera boom
 * see them, plus the terrain), registered by the collision runtime. Returns
 * the free distance and the object index that stopped it (-1 = terrain or
 * nothing). Null in a project whose terrain_game.hpp predates it. */
using WorldSweepFn = float (*)(float px, float py, float pz, float dx, float dy, float dz,
                               float maxDist, float radius, int skipIndex, int* hitObj);
inline WorldSweepFn g_worldSweep = nullptr;

// The fallback when the game registered no sweep: the Raycast node's
// bounding spheres (same marker skip list as the USE picker) + a terrain march.
inline float sphereRay(const ScriptContext& ctx, const Vec3& o, const Vec3& d, float maxDist,
                       int skip, int* hitObj) {
  *hitObj = -1;
  float best = maxDist;
  for (int i = 0; i < ctx.objectCount; ++i) {
    const RuntimeObject& r = ctx.objects[i];
    if (!r.active || !r.visible || i == skip) continue;
    const int ty = r.data.type;
    if (ty == 4 || ty == 6 || ty == 7 || ty == 8 || ty == 9 || ty == 11 || ty == 14 ||
        ty == 17 || ty == 18 || ty == 19 || ty == 20)
      continue;
    float half = r.data.scale[0];
    if (r.data.scale[1] > half) half = r.data.scale[1];
    if (r.data.scale[2] > half) half = r.data.scale[2];
    half *= 0.5F;
    const Vec3 c = Vec3::from(r.data.position) - o;
    const float tca = dot(c, d);
    if (tca < 0.0F || tca - half > best) continue;
    const float d2 = dot(c, c) - tca * tca;
    if (d2 > half * half) continue;
    float t = tca - sqrtf(half * half - d2);
    if (t < 0.0F) t = 0.0F;
    if (t < best) { best = t; *hitObj = i; }
  }
  float prev = 0.0F;
  for (float t = 0.5F; t <= best; t += 0.5F) {
    const Vec3 q = o + d * t;
    if (q.y <= terrainHeightAtScene(ctx.scene, q.x, q.z)) {
      float lo = prev, hi = t;
      for (int k = 0; k < 8; ++k) {
        const float mid = (lo + hi) * 0.5F;
        const Vec3 m = o + d * mid;
        if (m.y <= terrainHeightAtScene(ctx.scene, m.x, m.z)) hi = mid; else lo = mid;
      }
      best = hi;
      *hitObj = -1;
      break;
    }
    prev = t;
  }
  return best;
}
}  // namespace detail

/** A ray (radius 0) or a swept sphere (radius > 0) from `origin` along
 * `direction` (any length), up to maxDist: the first collision box or terrain
 * in the way. Objects without collision, markers and areas never stop it.
 * skip = an object index to ignore (yourself). */
inline RayHit raycast(ScriptContext& ctx, const Vec3& origin, const Vec3& direction,
                      float maxDist, float radius = 0.0F, int skip = -1) {
  RayHit h;
  const Vec3 d = normalize(direction);
  if (lengthSq(d) < 0.5F || maxDist <= 0.0F) return h;
  int obj = -1;
  const float t = detail::g_worldSweep
                      ? detail::g_worldSweep(origin.x, origin.y, origin.z, d.x, d.y, d.z,
                                             maxDist, radius, skip, &obj)
                      : detail::sphereRay(ctx, origin, d, maxDist, skip, &obj);
  h.hit = t < maxDist;
  h.distance = t;
  h.point = origin + d * t;
  if (h.hit && obj >= 0) h.object = ObjectRef(&ctx, obj);
  return h;
}
/** The Raycast node, exactly: from the player's eye along the view
 * direction, against what you can SEE - every visible object's bounding
 * sphere (collision or not; markers, lights and areas excluded) and the
 * terrain. raycast() above is the one for what blocks movement. */
inline RayHit raycastFromPlayer(ScriptContext& ctx, float maxDist = 100.0F) {
  RayHit h;
  const Vec3 o = ctx.playerPosition;
  const Vec3 d = normalize(ctx.playerLook);
  if (lengthSq(d) < 0.5F || maxDist <= 0.0F) {
    h.point = o;
    return h;
  }
  int obj = -1;
  const int player =
      ctx.scene >= 0 && ctx.scene < SCENE_COUNT ? PLAYER_INDEXES[ctx.scene] : -1;
  const float t = detail::sphereRay(ctx, o, d, maxDist, player, &obj);
  h.hit = t < maxDist;
  h.distance = t;
  h.point = o + d * t;
  if (obj >= 0) h.object = ObjectRef(&ctx, obj);
  return h;
}
/** Nothing solid between a and b (skip one object, e.g. the looker). */
inline bool lineOfSight(ScriptContext& ctx, const Vec3& a, const Vec3& b, int skip = -1) {
  const float d = distance(a, b);
  if (d < 1e-4F) return true;
  return !raycast(ctx, a, b - a, d, 0.0F, skip).hit;
}
/** Is the player inside this Area object (either player in two-player)? */
inline bool playerInArea(const ScriptContext& ctx, int areaIndex) {
  if (areaIndex < 0 || areaIndex >= ctx.objectCount || !ctx.objects[areaIndex].active)
    return false;
  const SceneObjectData& d = ctx.objects[areaIndex].data;
  if (pointInArea(d, ctx.playerPosition.x, ctx.playerPosition.y, ctx.playerPosition.z))
    return true;
  return ctx.player2Active &&
         pointInArea(d, ctx.player2Position.x, ctx.player2Position.y, ctx.player2Position.z);
}

// ---- input ----------------------------------------------------------------------
// Through the Input Map's actions (Tools > Input Map), so a rebind in the pause
// menu reaches scripts too. ActionId constants: tyrax::Actions::Jump, ...

inline bool actionHeld(ScriptContext& ctx, ActionId a) {
  return a.index >= 0 && inputPressed(ctx.engine->pad, a.index);
}
/** The frame the action went down (On Action). */
inline bool actionPressed(ScriptContext& ctx, ActionId a) {
  return a.index >= 0 && inputClicked(ctx.engine->pad, a.index);
}
/** 0..1 for an analog binding (triggers), 0/1 for a button. */
inline float actionValue(ScriptContext& ctx, ActionId a) {
  return a.index >= 0 ? inputAnalog(ctx.engine->pad, a.index) : 0.0F;
}
/** A stick as -1..1 per axis (x right, y DOWN on the pad), dead zone 0.12. */
inline Vec3 stick(ScriptContext& ctx, bool right = false) {
  const Tyra::PadJoy& j = right ? ctx.engine->pad.getRightJoyPad()
                                : ctx.engine->pad.getLeftJoyPad();
  float x = ((float)j.h - 128.0F) / 127.0F, y = ((float)j.v - 128.0F) / 127.0F;
  if (fabsf(x) < 0.12F) x = 0.0F;
  if (fabsf(y) < 0.12F) y = 0.0F;
  return Vec3(clamp(x, -1.0F, 1.0F), clamp(y, -1.0F, 1.0F), 0.0F);
}

// ---- audio ----------------------------------------------------------------------

namespace detail {
// Sound channel choice is shared with the flow graphs' Play Sound
// (docs/sound.md): channels 0..15 of the current room's reverb bus, an ended
// voice first, else the lowest priority strictly below the new sound's.
inline int g_sfxPrio[16] = {0};
inline int g_sfxPrioBus = -1;
inline void sfxSyncBus(int base) {
  if (g_sfxPrioBus == base) return;
  for (int i = 0; i < 16; ++i) g_sfxPrio[i] = 0;
  g_sfxPrioBus = base;
}
inline int pickSfxChannel(ScriptContext& ctx, int prio) {
  static int next = 0;
  const int base = ctx.reverbBusBase;
  sfxSyncBus(base);
  const u32 ended = ctx.engine->audio.adpcm.endedMask(base ? 0 : 1);
  for (int k = 0; k < 16; ++k) {
    const int c = (next + k) % 16;
    if (ended & (1u << c)) {
      next = (c + 1) % 16;
      g_sfxPrio[c] = prio;
      return base + c;
    }
  }
  int victim = -1, low = prio;
  for (int c = 0; c < 16; ++c)
    if (g_sfxPrio[c] < low) { low = g_sfxPrio[c]; victim = c; }
  if (victim < 0) return -1;
  g_sfxPrio[victim] = prio;
  return base + victim;
}
inline int pinSfxChannel(ScriptContext& ctx, int ch, int prio) {
  const int base = ctx.reverbBusBase;
  sfxSyncBus(base);
  if (ch >= 0 && ch < 16) g_sfxPrio[ch] = prio;
  return base + ch;
}
}  // namespace detail

/** Play Sound: volume 0..100, priority decides who loses a voice when all are
 * busy, channel >= 0 pins one. Returns the channel, -1 when it was dropped or
 * the sound is not loaded in this scene (Project > Audio says what loads it -
 * a sound only a script plays wants "Always loaded" or a bank). */
inline int playSound(ScriptContext& ctx, SoundId s, int volume = 100, int priority = 0,
                     int channel = -1) {
  if (s.index < 0) return -1;
  audsrv_adpcm_t* const sfx = soundbank::sample(s.index);
  if (!sfx) return -1;
  if (volume < 0) volume = 0;
  if (volume > 100) volume = 100;
  if (channel > 15) channel = 15;
  const int ch = channel >= 0 ? detail::pinSfxChannel(ctx, channel, priority)
                              : detail::pickSfxChannel(ctx, priority);
  if (ch < 0) return -1;
  ctx.engine->audio.adpcm.setVolume(volume * ctx.sfxVolume / 100, (s8)ch);
  ctx.engine->audio.reverb.setChannelSend((s8)ch, true);
  ctx.engine->audio.adpcm.forcePlay(sfx, (s8)ch);
  return ch;
}
/** Play Music: streams a track (stops the current one). */
inline void playMusic(ScriptContext& ctx, MusicId m, int volume = 100, bool loop = true) {
  if (!m.path || !m.path[0]) return;
  auto& song = ctx.engine->audio.song;
  song.stop();
  song.load(Tyra::FileUtils::fromCwd(m.path));
  song.inLoop = loop;
  song.setVolume(volume < 0 ? 0 : (volume > 100 ? 100 : volume));
  song.play();
}
inline void stopMusic(ScriptContext& ctx) { ctx.engine->audio.song.stop(); }
/** Set Sound Bank Loaded. */
inline void setSoundBankLoaded(SoundBankId b, bool loaded) {
  if (b.index >= 0) soundbank::setBank(b.index, loaded);
}
/** Set Reverb: preset 0..9 forced everywhere, -1 = back to the zones. */
inline void setReverb(ScriptContext& ctx, int preset, int amount = 50) {
  ctx.reverbPreset = preset;
  ctx.reverbAmount = amount;
}

